	ANGEBOT_NR VARCHAR(256) COMMENT 'Entspricht der angebot_nr aus PMR (dbp_data.angebot)',
	AKTIV_EINGESCHRAENKT_KUNDE_FG NUMBER(18,0) COMMENT 'Gibt an ob ein Coupon nur für eine bestimmte Kundengruppen bekommt. ',
