	WETTBEWERBER_FG NUMBER(18,0) COMMENT 'Gibt an ob es sich um ein Coupon von einem Wettbewerber handelt',
	CSR_FG NUMBER(18,0) COMMENT 'Gibt an ob es sich um einen CSR (Corporate Social Resposibility) Coupon handelt',
	LOYALTY_ARTIKEL_FG NUMBER(18,0) COMMENT 'Gibt an ob es sich um ein Loyalty Artikel Coupon handelt',
